package com.jarvis.phone;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.provider.Settings;import android.speech.RecognizerIntent;import android.speech.tts.TextToSpeech;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{LocalVault vault;EditText wake,cmd;TextView status;TextToSpeech tts;static final int SPEECH=90;public void onCreate(Bundle b){super.onCreate(b);vault=new LocalVault(this);tts=new TextToSpeech(this,s->{if(s==0)tts.setLanguage(new Locale("hi","IN"));});LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(28,28,28,28);TextView title=new TextView(this);title.setText("Jarvis Phone v2\nPHONE-ONLY • LOCAL-FIRST • VOICE-FIRST");title.setTextSize(23);x.addView(title);wake=new EditText(this);wake.setHint("Wake name");wake.setText(vault.get("wake_name","Jarvis"));x.addView(wake);add(x,"Save name",()->{vault.put("wake_name",wake.getText().toString().trim());say("नाम सेव हो गया।");});add(x,"Start listening",this::startWake);add(x,"Stop listening",()->{stopService(new Intent(this,WakeWordService.class));status.setText("Voice listener बंद।");});add(x,"Speak once",this::speakOnce);cmd=new EditText(this);cmd.setHint("Optional typing fallback");x.addView(cmd);add(x,"Run command",()->new CommandEngine(this).execute(cmd.getText().toString(),this::say));add(x,"Screen Control permission",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));add(x,"Notification Access",()->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS")));add(x,"Clear local memory",()->{vault.clear();wake.setText("Jarvis");say("Local memory साफ़।");});status=new TextView(this);status.setText("Ready. Start listening दबाकर बोलो: Jarvis YouTube खोलो");x.addView(status);ScrollView s=new ScrollView(this);s.addView(x);setContentView(s);request();}void add(LinearLayout x,String n,Runnable r){Button b=new Button(this);b.setText(n);b.setOnClickListener(v->r.run());x.addView(b);}void request(){ArrayList<String>p=new ArrayList<>();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.POST_NOTIFICATIONS);if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),33);}void startWake(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){request();return;}startForegroundService(new Intent(this,WakeWordService.class));status.setText("Voice listener चालू। बोलो: Jarvis YouTube खोलो");}void speakOnce(){Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"hi-IN");i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);try{startActivityForResult(i,SPEECH);}catch(Exception e){say("Speech recognizer नहीं मिला।");}}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==SPEECH&&c!=RESULT_OK){say("Voice पहचान नहीं हुई। Google speech service जाँचें।");}if(r==SPEECH&&c==RESULT_OK&&d!=null){ArrayList<String>a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){cmd.setText(a.get(0));new CommandEngine(this).execute(a.get(0),this::say);}}}void say(String s){runOnUiThread(()->{status.setText(s);if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"main");});}protected void onDestroy(){if(tts!=null)tts.shutdown();super.onDestroy();}}
